insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 160, 'B5.7.12', 'Význam pojmu „úvěrové riziko“(odstavce 5.7.7a5.7.8)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 161, 'B5.7.15', 'a) závazek obsahující prvek, který výši plnění váže na hodnotu podílové jednotky (unit-linking feature), kdy je částka splatná investorům smluvně stanovena na základě výkonnosti určitých aktiv. Dopad tohoto prvku, který výši plnění váže na hodnotu podílové jednotky (unit-linking feature) na reálnou hodnotu závazku představuje riziko výkonnosti specifické pro určitá aktiva, nikoli úvěrové riziko; b) závazek vydaný strukturovanou účetní jednotkou s následujícími znaky. Účetní jednotka je právně izolovaná, tudíž aktiva v této jednotce jsou účelově vázaná pouze ve prospěch svých investorů, i v případě úpadku. Účetní jednotka neuzavírá žádné další transakce a aktiva této jednotky nemohou být zastavena. Částky náleží investorům účetní jednotky, pouze pokud účelově vázaná aktiva generují peněžní toky. Změny v reálné hodnotě závazku tudíž odrážejí především změny v reálné hodnotě aktiva. Dopad výkonnosti aktiva na reálnou hodnotu závazku představuje riziko výkonnosti specifické pro určitá aktiva, nikoli úvěrové riziko. Určování dopadů změn úvěrového rizika'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 162, 'B5.7.16', 'a) jako výši změny v reálné hodnotě, která nenastala v důsledku změn tržních podmínek, které způsobují vznik tržního rizika (viz odstavce B5.7.17 a B5.7.18), nebo b) pomocí jiné metody, která dle účetní jednotky věrněji zobrazuje výši změny v reálné hodnotě daného závazku v důsledku změn úvěrového rizika, které je s ním spojeno.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 163, 'B5.7.18', 'a) nejprve účetní jednotka vypočítá vnitřní výnosovou míru závazku na počátku období pomocí zjištěné reálné hodnoty závazku a smluvních peněžních toků závazku na počátku období. Od této vnitřní výnosové míry odečte pozorovanou (referenční) úrokovou míru na počátku období a dostane složku vnitřní výnosové míry příslušející určitému nástroji; b) účetní jednotka dále vypočítá současnou hodnotu peněžních toků spojených se závazkem s pomocí smluvních peněžních toků závazku na konci období a diskontní sazby rovnající se součtu i) pozorované (referenční) úrokové míry na konci období a ii) složky vnitřní výnosové míry, která přísluší danému nástroji a která byla určena podle písmene a); c) rozdíl mezi reálnou hodnotou závazku na konci období a částkou určenou podle písmene b) představuje změnu reálné hodnoty, která nevyplývá ze změn pozorované (referenční) tržní úrokové míry. To je částka, kterou je třeba vykázat do ostatního úplného výsledku v souladu s odst. 5.7.7 písm. a).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 164, 'ZAJIŠŤOVACÍ ÚČETNICTVÍ (KAPITOLA 6)', 'Zajišťovací nástroje (oddíl 6.2) Co může být zajišťovacím nástrojem'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 165, 'B6.2.3', 'Vystavené opce'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 166, 'B6.2.4', 'Použití zajišťovacího nástroje'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 167, 'B6.2.6', 'Zajištěné položky (oddíl 6.3) Co může být zajištěnou položkou'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 168, 'B6.3.3', 'a) účetní jednotka může zajistit určité množství vysoce pravděpodobných koupí kávy za období 15 měsíců proti cenovému riziku (na základě US dolarů) pomocí patnáctiměsíčních smluv typu futures na kávu. Kombinaci vysoce pravděpodobných koupí kávy a smlouvy typu futures na kávu lze pro účely řízení rizika považovat za patnáctiměsíční angažovanost vůči měnovému riziku stanovenou pevnou částkou v US dolarech (tj. jako jakýkoli peněžní odtok stanovený pevnou částkou v US dolarech za období 15 měsíců);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 169, 'B6.3.3', 'b) účetní jednotka může zajistit měnové riziko na celé období desetiletého dluhu s pevnou úrokovou mírou, vyjádřeného v cizí měně. Účetní jednotka však vyžaduje, aby byla angažovanost s pevnou úrokovou mírou uváděna v její funkční měně pouze v krátkodobém až střednědobém horizontu (dejme tomu dvouletém) a angažovanost s pohyblivou úrokovou mírou v její funkční měně po zbývající dobu do splatnosti. Na konci každého z těchto dvouletých intervalů (tj. s dvouletým přeceňováním) stanoví účetní jednotka úrokovou angažovanost na následující dva roky (pokud je výše úroku taková, že si účetní jednotka přeje zafixovat úrokové míry). V takové situaci může účetní jednotka uzavřít desetiletý měnový úrokový swap se změnou z pevné úrokové míry na pohyblivou, který mění dluh v cizí měně s pevnou úrokovou mírou na angažovanost ve funkční měně s proměnlivou úrokovou mírou. Ten se překrývá s dvouletým úrokovým swapem, který – na základě funkční měny – mění dluh s proměnlivou úrokovou mírou na dluh s pevnou úrokovou mírou. V podstatě je na kombinaci dluhu v cizí měně s pevnou úrokovou mírou a desetiletého měnového úrokového swapu se změnou z pevné úrokové míry na pohyblivou pro účely řízení rizika nahlíženo jako na desetiletou angažovanost dluhu s proměnlivou úrokovou mírou ve funkční měně.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 170, 'B6.3.4', 'a) deriváty, které jsou součástí agregované expozice, se uznají jako samostatná aktiva nebo závazky oceňované reálnou hodnotou a b) pokud je zajišťovací vztah zařazen mezi položky, které představují agregovanou expozici, musí být způsob, kterým je derivát zahrnut do agregované expozice, v souladu s určením tohoto derivátu jako zajišťovacího nástroje na úrovni agregované expozice. Jestliže například účetní jednotka vylučuje forwardový prvek derivátu z jeho určení jako zajišťovacího nástroje pro zajišťovací vztah mezi položkami, které představují agregovanou expozici, musí tento forwardový prvek vyloučit rovněž při zahrnutí derivátu jako zajištěné položky jako části celkové expozice. Jinak musí celková expozice zahrnovat derivát jako celek nebo jeho poměrnou část.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 171, 'B6.3.6', 'Použití zajištěných položek'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 172, 'B6.3.7', 'Rizikové složky'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 173, 'B6.3.10', 'a) účetní jednotka A má dlouhodobou smlouvu o dodávkách zemního plynu, jehož cena se určuje pomocí smluvně stanoveného vzorce odkazujícího na komodity a další faktory (například plynový olej, topný olej a ostatní složky, jako jsou například platby za dopravu). Účetní jednotka A zajistí složku plynového oleje v této smlouvě o dodávkách pomocí forwardové smlouvy na plynový olej. Vzhledem k tomu, že složka plynového oleje je specifikována v podmínkách smlouvy o dodávkách, jedná se o smluvně určenou složku rizika. Proto účetní jednotka A na základě vzorce pro stanovení cen dospěje k závěru, že riziko ceny plynového oleje je samostatně identifikovatelné. Zároveň existuje trh pro forwardové smlouvy na plynový olej. Proto účetní jednotka A dospěje k závěru, že riziko ceny plynového oleje je spolehlivě měřitelné. V důsledku toho představuje riziko ceny plynového oleje ve smlouvě o dodávkách složku, která je způsobilá k určení jako zajištěná položka; b) účetní jednotka B zajistí své budoucí koupě kávy na základě své předpokládané produkce. Pro část předpokládaného objemu prodeje je zajištění zahájeno až 15 měsíců před dodávkou. Účetní jednotka B v průběhu času zvyšuje objem zajištění (s přibližováním data dodávky). Účetní jednotka B používá pro řízení svého cenového rizika kávy dva odlišné typy smluv: i) smlouvy typu futures na kávu obchodované na burze a'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 174, 'B6.3.10', 'ii) smlouvy na dodávky kávy Arabica z Kolumbie dodávané na konkrétní místo výroby. Tyto smlouvy určují cenu tuny kávy na základě ceny smluv typu futures na kávu obchodovaných na burze, pevného cenového diferenciálu a proměnlivého poplatku za logistické služby s pomocí vzorce pro stanovení cen. Smlouva o dodávkách kávy představuje dosud nesplněnou smlouvu, v souladu s níž účetní jednotka provede skutečnou dodávku kávy.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 175, 'B6.3.10', 'U dodávek, které se vztahují ke sklizni v daném roce, umožní uzavření smluv o dodávkách kávy účetní jednotce B stanovit cenový diferenciál mezi skutečnou kvalitou zakoupené kávy (kávy Arabica z Kolumbie) a referenční kvalitou, která slouží jako podkladová proměnná pro smlouvu typu futures obchodovanou na burze. Pro dodávky vztahující se k příští sklizni však smlouvy na dodávku kávy nejsou dosud k dispozici, takže není možné stanovit cenový diferenciál. Účetní jednotka B použije smlouvu typu futures obchodovanou na burze kávy k zajištění složky referenční kvality svého cenového rizika kávy pro dodávky vztahující se jak ke sklizni v daném roce, tak k příští sklizni. Účetní jednotka B určí, že je vystavena třem odlišným rizikům: cenovému riziku kávy odrážejícímu referenční kvalitu, cenovému riziku kávy odrážejícímu rozdíl (rozpětí) mezi cenou referenční kvality kávy a určité kávy Arabica z Kolumbie, kterou skutečně obdrží, a proměnlivé logistické náklady. U dodávek týkajících se sklizně v daném roce bude poté, co účetní jednotka B uzavře smlouvu o dodávkách kávy, cenové riziko odrážející referenční kvalitu smluvně určenou složkou rizika, protože vzorec pro stanovení cen zahrnuje indexaci na cenu smlouvy typu futures obchodované na burze kávy. Účetní jednotka B dospěje k závěru, že tato složka rizika je samostatně identifikovatelná a spolehlivě ocenitelná. U dodávek týkajících se příští sklizně účetní jednotka B dosud neuzavřela žádné smlouvy na dodávku kávy (tj. tyto dodávky jsou očekávanými transakcemi). Cenové riziko kávy odrážející referenční kvalitu je tedy mimosmluvně určenou složkou rizika. Analýza tržní struktury provedená účetní jednotkou B zohledňuje způsob stanovení cen případných dodávek této určité kávy, kterou obdrží. Proto účetní jednotka B na základě této analýzy tržní struktury dospěje k závěru, že očekávané transakce zahrnují rovněž cenové riziko kávy, které odráží referenční kvalitu jako složku rizika, která je samostatně identifikovatelná a spolehlivě ocenitelná i přesto, že není smluvně určena. V důsledku toho může účetní jednotka B použít zajišťovací vztahy založené na složkách rizika (pro cenové riziko kávy, které odráží referenční kvalitu) pro smlouvy na dodávku kávy i pro očekávané transakce;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 176, 'B6.3.10', 'c) účetní jednotka C zajistí část svých budoucích koupí leteckého turbínového paliva na základě své předpokládané spotřeby až 24 měsíců před dodávkou a v průběhu času bude objem zajištění zvyšovat. Účetní jednotka C zajistí toto riziko s využitím různých typů smluv v závislosti na časovém horizontu zajištění, který ovlivňuje tržní likviditu derivátů. Pro delší časové horizonty (12–24 měsíců) používá účetní jednotka C kontrakty na surovou ropu, protože jen tyto kontrakty mají dostatečnou tržní likviditu. Pro časové horizonty 6–12 měsíců užívá účetní jednotka C deriváty na plynový olej, protože jsou dostatečně likvidní. Pro časové horizonty do šesti měsíců užívá účetní jednotka C kontrakty na letecké turbínové palivo. Analýza tržní struktury pro ropu a ropné produkty provedená společností C a její vyhodnocení relevantních skutečností a okolností je následující: i) účetní jednotka C působí v zeměpisné oblasti, v níž se jako referenční údaj používá surová ropa typu Brent. Surová ropa je referenčním údajem surovin, který ovlivňuje cenu různých ropných produktů jako jejich nejdůležitější vstup. Plynový olej je referenčním měřítkem rafinovaných ropných produktů, kterého se užívá jako reference při tvorbě cen destilátů ropy obecněji. To se odráží rovněž v typech derivátových finančních nástrojů pro trhy s ropou a rafinovanými ropnými produkty v prostředí, v němž účetní jednotka C působí, jako například: — referenční smlouva typu futures na ropu týkající se surové ropy Brent, —'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 177, 'B6.3.10', 'referenční smlouva typu futures na plynový olej, která se užívá jako reference pro tvorbu cen destilátů – například spreadové deriváty leteckého turbínového paliva pokrývají cenový diferenciál mezi leteckým turbínovým palivem a referenčním plynovým olejem, — referenční derivát „crack spread“ u plynového oleje, (tj. derivát pro cenový diferenciál mezi ropou a plynovým olejem – rafinérská marže), který je indexovaný k ropě typu Brent; ii) stanovení cen rafinovaných ropných produktů nezávisí na tom, která konkrétní ropa je zpracovávána v určité rafinérii, protože tyto rafinované ropné produkty (jako například plynový olej nebo tryskové palivo) jsou standardizované produkty. Proto dospěje účetní jednotka C k závěru, že cenové riziko jejích koupí leteckého turbínového paliva zahrnuje složku cenového rizika surové ropy vycházející ze surové ropy typu Brent, a složku cenového rizika plynového oleje, i když surová ropa ani plynový olej nejsou specifikovány v žádném smluvním ujednání. Účetní jednotka C dospěje k závěru, že tyto dvě složky rizika lze samostatně identifikovat a spolehlivě ocenit, i když nejsou smluvně určené. V důsledku toho může účetní jednotka C použít zajišťovací vztahy pro předpokládané koupě tryskového paliva na základě složek rizika (pro surovou ropu nebo plynový olej). Tato analýza rovněž znamená, že pokud by účetní jednotka C použila například deriváty surové ropy na základě ropy West Texas Intermediate (WTI), změny cenového diferenciálu mezi ropou Brent a ropou WTI by způsobily neefektivnost zajištění;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 178, 'B6.3.10', 'd) účetní jednotka D drží dluhový nástroj s pevnou úrokovou mírou. Tento nástroj je vydán v prostředí s trhem, na němž je velké množství podobných dluhových nástrojů porovnáváno podle svých rozpětí s referenční úrokovou mírou (například LIBOR) a nástrojů s proměnlivou úrokovou mírou, které jsou v tomto prostředí obvykle indexovány k této referenční sazbě. Pro řízení úrokového rizika se často používají úrokové swapy na základě této referenční sazby bez ohledu na rozpětí dluhových nástrojů vůči této referenční sazbě. Cena dluhového nástroje s pevnou úrokovou mírou se mění v přímé reakci na změny referenční sazby tak, jak nastávají. Účetní jednotka D dospěje k závěru, že referenční sazba představuje složku, kterou lze samostatně identifikovat a spolehlivě ocenit. V důsledku toho může účetní jednotka D použít zajišťovací vztahy pro dluhový nástroj s pevnou úrokovou mírou na základě složky rizika pro referenční úrokové riziko.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 179, 'B6.3.15', 'Složky nominální hodnoty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 180, 'B6.3.18', 'a) část objemu finanční transakce, například příští peněžní toky v hodnotě 10 CM z prodeje vyjádřené v cizí měně následující po prvních 20 CM v březnu 201X (54); b) část fyzického objemu, například spodní vrstva, oceňující 5 milionů krychlových metrů zemního plynu uskladněného v lokalitě XYZ; c) část fyzického nebo jiného objemu transakce, například koupě prvních 100 barelů ropy v červnu 201X nebo prvních 100 MWh prodeje elektřiny v červnu 201X; d) vrstvu nominální hodnoty zajištěné položky. Například posledních 80 milionů MJ ze závazného příslibu ve výši 100 milionů MJ, spodní vrstva 20 milionů MJ z dluhopisu s pevnou úrokovou mírou 100 milionů MJ nebo horní vrstva 30 milionů MJ z celkové částky dluhu s pevnou úrokovou mírou ve výši 100 milionů MJ, který lze předčasně splatit v reálné hodnotě (definovaná nominální hodnota je 100 milionů MJ).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 181, 'B6.3.20', 'Vztah mezi složkami a celkovými peněžními toky určité položky'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 182, 'B6.3.22', 'a) složku závazku rovnající se úroku při použití úrokové míry LIBOR (plus částka jistiny v případě zajištění reálné hodnoty) a b) zápornou zbytkovou složku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 183, 'B6.3.25', 'Kritéria pro použití zajišťovacího účetnictví (oddíl 6.4) Efektivnost zajištění'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 184, 'B6.4.3', 'Ekonomický vztah mezi zajištěnou položkou a zajišťovacím nástrojem'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 185, 'B6.4.6', 'Dopad úvěrového rizika'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 186, 'B6.4.8', 'Zajišťovací poměr'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 187, 'B6.4.11', 'a) zda je stanoven zamýšlený zajišťovací poměr s cílem předejít uznání neefektivnosti zajištění u zajištění peněžních toků nebo dosáhnout úprav zajištění reálné hodnoty pro více zajištěných položek s cílem zvýšit využívání účtování v reálné hodnotě, ale bez vzájemného započtení změn reálné hodnoty zajišťovacího nástroje, a b) zda existuje obchodní důvod pro konkrétní poměrné váhy zajištěné položky a zajišťovacího nástroje, i když to vede k neefektivnosti zajištění. Účetní jednotka například uzavře zajišťovací nástroj a určí jeho množstevní položky, které se neshodují s množstevními položkami stanovenými jako nejlepší zajištění zajištěné položky, protože standardní objem zajišťovacích nástrojů jí neumožňuje použít přesný počet množstevních položek zajišťovacího nástroje („problematika velikosti lotů“). Příkladem je účetní jednotka, která zajišťuje koupi 100 tun kávy pomocí standardních smluv typu futures, přičemž velikost smlouvy je 37 500 liber. Účetní jednotka by mohla na zajištění objemu koupě 100 tun použít pouze pět nebo šest smluv (což odpovídá 85,0 a 102,1 tunám). V tomto případě účetní jednotka označí zajišťovací vztah pomocí zajišťovacího poměru vyplývajícího z počtu smluv typu futures na koupi kávy, které skutečně využívá, protože neefektivnost zajištění vyplývající z nesouladu poměrných vah zajištěné položky a zajišťovacího nástroje by nevyústila v účetní výsledek, který by byl v rozporu s účelem zajišťovacího účetnictví. Četnost posuzování, zda jsou splněny požadavky na efektivnost zajištění'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 188, 'B6.4.12', 'Metody posuzování, zda jsou splněny požadavky na efektivnost zajištění'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 189, 'B6.4.19', 'Účtování o zajišťovacích vztazích splňujících podmínky (oddíl 6.5)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 190, 'B6.5.3', 'Vyčíslení neefektivnosti zajištění'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 191, 'B6.5.6', 'Rebalancování zajišťovacího vztahu a změn zajišťovacího poměru'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 192, 'B6.5.11', 'a) výkyvy oproti zajišťovacímu poměru, který zůstává i nadále platný (tj. i nadále vhodně odráží vztah mezi zajišťovacím nástrojem a zajištěnou položkou), nebo b) známky toho, že zajišťovací poměr již vhodně neodráží vztah mezi zajišťovacím nástrojem a zajištěnou položkou. Účetní jednotka provede toto vyhodnocení v porovnání s požadavkem na efektivnost zajištění zajišťovacího poměru, tj. s cílem zajistit, že zajišťovací vztah neodráží takovou nerovnováhu mezi poměrnými vahami zajištěné položky a zajišťovacího nástroje, která by způsobila neefektivnost zajištění (bez ohledu na to, zda by byla uznána, či nikoli), a jejímž důsledkem by mohl být účetní výsledek, který by byl v rozporu s účelem zajišťovacího účetnictví. Proto toto posouzení vyžaduje použití úsudku.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 193, 'B6.5.14', 'a) by zajišťovací poměr vyplývající ze změny počtu množstevních jednotek zajišťovacího nástroje nebo zajištěné položky, které účetní jednotka skutečně využívá, odrážel nerovnováhu, která by způsobila neefektivnost zajištění a jejímž důsledkem by mohl být účetní výsledek, který by byl v rozporu s účelem zajišťovacího účetnictví, nebo b) by účetní jednotka zachovala počet množstevních jednotek zajišťovacího nástroje a zajištěné položky, které skutečně využívá, a v důsledku toho by vznikl zajišťovací poměr, který by za nových okolností odrážel nerovnováhu, která by způsobila neefektivnost zajištění a jejímž důsledkem by mohl být účetní výsledek, který by byl v rozporu s účelem zajišťovacího účetnictví; (tj. účetní jednotka nesmí vytvořit nerovnováhu tím, že opomene upravit zajišťovací poměr).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 194, 'B6.5.16', 'a) lze zvýšit váhu zajištěné položky (což zároveň snižuje váhu zajišťovacího nástroje): i) zvýšením objemu zajištěné položky, nebo ii) snížením objemu zajišťovacího nástroje; b) lze zvýšit váhu zajišťovacího nástroje (což zároveň snižuje váhu zajištěné položky): i) zvýšením objemu zajišťovacího nástroje, nebo ii) snížením objemu zajištěné položky. Změny objemu se týkají počtu množstevních jednotek, které jsou součástí zajišťovacího vztahu. Snížení objemu tedy nemusí nutně znamenat, že dané položky nebo transakce již neexistují nebo se již nepředpokládá, že proběhnou, ale pouze to, že již nejsou součástí zajišťovacího vztahu. Důsledkem snížení objemu zajišťovacího nástroje může být například to, že si účetní jednotka podrží určitý derivát, ale pouze část tohoto derivátu bud moci být i nadále zajišťovacím nástrojem v zajišťovacím vztahu. K tomu by mohlo dojít, pokud by se rebalancování mohlo uskutečnit pouze snížením objemu zajišťovacího nástroje v zajišťovacím vztahu, ale účetní jednotka by si přitom podržela i objem, který už není zapotřebí. V takovém případě by byla neoznačená část derivátu účtována v reálné hodnotě do hospodářského výsledku (pokud by nebyla označena jako zajišťovací nástroj v jiném zajišťovacím vztahu).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 195, 'B6.5.21', 'Ukončení zajišťovacího účetnictví'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 196, 'B6.5.23', 'a) i nadále splňuje cíle řízení rizik, na základě kterého se stal způsobilým pro zajišťovací účetnictví (tj. účetní jednotka i nadále splňuje tento cíl řízení rizik), a b) nadále splňuje všechna ostatní kritéria způsobilosti (po zohlednění případného rebalancování zajišťovacího vztahu, připadá-li v úvahu).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 197, 'B6.5.24', 'a) účetní jednotka má strategii řízení svého úrokového rizika u dluhového financování, která stanoví pro účetní jednotku jako celek rozpětí kombinace financování s proměnlivou úrokovou mírou a s pevnou úrokovou mírou. Tato strategie spočívá v udržení pevné úrokové míry u 20 až 40 procent dluhu. Účetní jednotka se čas od času rozhodne, jak tuto strategii provádět (tj. ve které části rozpětí 20 až 40 procent rizika s pevnou úrokovou mírou se hodlá pohybovat) v závislosti na výši úrokových měr. Pokud jsou úrokové míry nízké, stanoví účetní jednotka pevnou úrokovou míru pro větší část dluhu než v případě, že jsou úrokové míry vysoké. Dluh účetní jednotky činí 100 MJ dluhu s proměnlivou úrokovou mírou, z nichž 30 MJ je vyměněno za dluh s pevnou úrokovou mírou. Účetní jednotka využije nízkých úrokových měr a vydá další dluh ve výši 50 MJ za účelem financování větší investice, což realizuje pomocí emise dluhopisu s pevnou úrokovou mírou. Vzhledem k nízkým úrokovým mírám se účetní jednotka rozhodne stanovit riziko s pevnou úrokovou mírou na 40 procent celkového dluhu, přičemž o 20 MJ sníží rozsah, v němž dříve zajišťovala své riziko s proměnlivou úrokovou mírou, což znamená, že výsledné riziko s pevnou úrokovou mírou bude činit 60 MJ. V této situaci se strategie řízení rizik jako taková nemění. Změnil se však způsob, jímž účetní jednotka tuto strategii provádí, což znamená, že došlo ke změně cíle řízení rizika s proměnlivou úrokovou mírou ve výši 20 MJ, které bylo dříve zajištěno (tj. na úrovni zajišťovacího vztahu). Proto je v této situaci nutno ukončit zajišťovací účetnictví pro 20 MJ dříve zajištěného rizika s proměnlivou úrokovou mírou. To by mohlo zahrnovat snížení swapové pozice o 20 MJ nominální hodnoty, ale účetní jednotka by si v závislosti na okolnostech mohla tento objem swapu ponechat a použít ho například k zajištění jiného rizika, případně by se mohl stát součástí obchodního portfolia. Jestliže naopak účetní jednotka místo toho vyměnila část svého nového dluhu s pevnou úrokovou mírou za riziko s proměnlivou úrokovou mírou, bylo by nutné u dříve zajištěného rizika s proměnlivou úrokovou mírou v zajišťovacím účetnictví pokračovat;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 198, 'B6.5.24', 'b) některá rizika vznikají na základě pozic, které se často mění, například úrokové riziko otevřeného portfolia dluhových nástrojů. Přidávání nových dluhových nástrojů a vynětí dluhových nástrojů toto riziko průběžně mění (tj. riziko se liší pouze v důsledku ukončení pozice, jejíž splatnost nastala). Jedná se o dynamický proces, ve kterém ani riziko, ani zajišťovací nástroje používané k jeho řízení nezůstávají dlouho beze změny. V důsledku toho účetní jednotka s takovým rizikem často upravuje zajišťovací nástroje používané k řízení úrokového rizika podle toho, jak se toto riziko mění. Například dluhové nástroje se zbytkovou splatností 24 měsíců jsou označeny jako zajištěná položka ve vztahu k úvěrovému riziku na 24 měsíců. Stejný postup se uplatní i u jiných časových skupin nebo období splatnosti. Po krátké době účetní jednotka přeruší všechny, některé nebo část dříve určených zajišťovacích vztahů pro určité období splatnosti a určí nové zajišťovací vztahy pro období splatnosti na základě jejich velikosti a zajišťovacích nástrojů, které v dané době existují. Přerušení zajišťovacího účetnictví v této situaci odráží skutečnost, že tyto zajišťovací vztahy jsou nastaveny tak, že účetní jednotka zohledňuje nový zajišťovací nástroj a novou zajištěnou položku namísto zajišťovacího nástroje a zajištěné položky, které byly označeny původně. Strategie řízení rizik zůstává stejná, ale pro tyto původně označené zajišťovací vztahy, které samy o sobě již neexistují, neexistuje cíl řízení rizik. V této situaci se uplatní přerušení zajišťovacího účetnictví v takovém rozsahu, v němž se změnil cíl řízení rizik. To závisí na situaci účetní jednotky a mohlo by to ovlivnit například všechny nebo jen některé zajišťovací vztahy v rámci daného období splatnosti, případně jen část zajišťovacího vztahu;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 199, 'B6.5.24', 'c) účetní jednotka má strategii řízení rizik, s jejíž pomocí řídí měnové riziko očekávaných prodejů a výsledných pohledávek. V rámci této strategie účetní jednotka řídí měnové riziko jako konkrétní zajišťovací vztah jen do doby uznání dané pohledávky. Poté účetní jednotka již neřídí měnové riziko na základě tohoto konkrétního zajišťovacího vztahu. Namísto toho řídí společně měnové riziko vyplývající z pohledávek, závazků a derivátů (které se nevztahují k očekávaným transakcím, které dosud neproběhly) vyjádřených v téže cizí měně. Pro účely účtování to funguje jako „přirozené“ zajištění vzhledem k tomu, že zisky a ztráty z měnového rizika u všech těchto položek jsou bezprostředně uznány do hospodářského výsledku. V důsledku toho pro účely účtování platí, že jestliže je zajišťovací vztah označen pro období před datem úhrady, musí být přerušen v okamžiku, kdy je pohledávka uznána, protože cíl řízení rizik původního zajišťovacího vztahu již neplatí. Měnové riziko je nyní řízeno v rámci téže strategie, ale na odlišném základě. Naproti tomu jestliže účetní jednotka měla odlišný cíl řízení rizik a řídila měnové riziko jako jediný souvislý zajišťovací vztah konkrétně pro danou částku očekávaného prodeje a výslednou pohledávku až do data vypořádání, zajišťovací účetnictví by pokračovalo až do tohoto data.')
